package com.loja.checkout.pagamento;

import com.loja.checkout.Arredondamento;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;

@Component
public class Cartao implements FormaPagamento {

    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
    private static final int PARCELAS_SEM_JUROS = 3;

    @Override
    public String codigo() {
        return "CARTAO";
    }

    @Override
    public boolean isParcelasValido(int parcelas) {
        return parcelas >= 1 && parcelas <= 12;
    }

    @Override
    public boolean isDisponivel(BigDecimal totalPedido) {
        return true;
    }

    @Override
    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
        if (parcelas <= PARCELAS_SEM_JUROS) {
            BigDecimal valorParcela = Arredondamento.centavos(
                    totalPedido.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
            BigDecimal totalFinal = totalPedido;
            return new ResultadoPagamento(totalFinal, valorParcela, parcelas);
        }

        // Tabela Price: parcela = total × taxa / (1 − (1 + taxa)^−n)
        double taxa = TAXA_MENSAL.doubleValue();
        double total = totalPedido.doubleValue();
        double parcela = total * taxa / (1 - Math.pow(1 + taxa, -parcelas));
        BigDecimal valorParcela = Arredondamento.centavos(BigDecimal.valueOf(parcela));
        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
        return new ResultadoPagamento(totalFinal, valorParcela, parcelas);
    }
}

